func (s *Server) handlePageLoginPOSTSubmit(
	w http.ResponseWriter, r *http.Request,
) {
	if !s.checkIsDSReq(w, r) {
		return
	}
	// CSRF protection covers every state-changing action, including
	// the ones that read nothing of the session.
	if _, _, ok := s.auth(w, r); !ok {
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, DefaultBodySizeLimit)
	var signals struct {
		User     string `json:"user"`
		Nickname string `json:"nickname"`
	}
	if err := datastar.ReadSignals(r, &signals); err != nil {
		s.httpErrBad(w, "reading signals", err)
		return
	}
	p := app.PageLogin{
		App: s.app,
	}
	newSession, redirect, err := p.POSTSubmit(r, signals)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling action PageLogin.Submit", err)
		return
	}
	if j := newSession; j.UserID != "" {
		if err := s.createSession(w, r, newSession); err != nil {
			s.httpErrIntern(w, r, nil, "creating session", err)
			return
		}
	}
	if httpRedirect(w, r, redirect) {
		return
	}
}

func (s *Server) handlePageLoginPOSTNotify(
	w http.ResponseWriter, r *http.Request,
) {
	if !s.checkIsDSReq(w, r) {
		return
	}
	// CSRF protection covers every state-changing action, including
	// the ones that read nothing of the session.
	if _, _, ok := s.auth(w, r); !ok {
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, DefaultBodySizeLimit)
	var signals struct {
		User string `json:"user"`
		Text string `json:"text"`
	}
	if err := datastar.ReadSignals(r, &signals); err != nil {
		s.httpErrBad(w, "reading signals", err)
		return
	}

	dispatchNotice := func(
		e app.EventNotice,
		options ...datapages.DispatchOption,
	) error {
		conf := datapages.DispatchConfig{Context: r.Context()}
		for _, o := range options {
			o(&conf)
		}
		if !isSubjectToken(string(e.Recipient)) {
			return fmt.Errorf(
				"EventNotice.Recipient must be a non-empty subject token, received %q",
				e.Recipient)
		}
		j, err := json.Marshal(e)
		if err != nil {
			return fmt.Errorf("marshaling EventNotice JSON: %w", err)
		}
		subj := "notice." + string(e.Recipient)
		err = s.messageBroker.Publish(conf.Context, s.messageBrokerMetrics, subj, j)
		if err != nil {
			return fmt.Errorf("publishing subject %q: %w", subj, err)
		}
		return nil
	}
	p := app.PageLogin{
		App: s.app,
	}
	err := p.POSTNotify(r, signals, dispatchNotice)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling action PageLogin.Notify", err)
		return
	}
}

